import itertools

def get_neighbors(r, c, N):
    neighbors = []
    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < N and 0 <= nc < N:
            neighbors.append((nr, nc))
    return neighbors

def count_good_paths(board, N):
    f = [[0] * N for _ in range(N)]
    cells = []
    for r in range(N):
        for c in range(N):
            cells.append((board[r][c], r, c))
    cells.sort()

    total_paths = 0
    for val, r, c in cells:
        neighbors = get_neighbors(r, c, N)
        smaller_neighbors = [n for n in neighbors if board[n[0]][n[1]] < val]

        if not smaller_neighbors:
            f[r][c] = 1
        else:
            f[r][c] = sum(f[nr][nc] for nr, nc in smaller_neighbors)
        total_paths += f[r][c]

    return total_paths

def solve_small(N):
    import itertools
    min_paths = float('inf')
    # For N=2, there are 4! = 24 permutations
    for p in itertools.permutations(range(1, N*N + 1)):
        board = [p[i*N:(i+1)*N] for i in range(N)]
        min_paths = min(min_paths, count_good_paths(board, N))
    return min_paths

print(f"N=2: {solve_small(2)}")

