def solve_small_simulated_annealing(N):
    import random

    def get_score(board):
        return count_good_paths(board, N)

    # Initialize
    board = [[0]*N for _ in range(N)]
    vals = list(range(1, N*N+1))
    random.shuffle(vals)
    idx = 0
    for r in range(N):
        for c in range(N):
            board[r][c] = vals[idx]
            idx += 1

    current_score = get_score(board)
    min_score = current_score

    T = 10.0
    alpha = 0.999
    for i in range(10000):
        # Swap two random elements
        r1, c1 = random.randint(0, N-1), random.randint(0, N-1)
        r2, c2 = random.randint(0, N-1), random.randint(0, N-1)

        board[r1][c1], board[r2][c2] = board[r2][c2], board[r1][c1]
        new_score = get_score(board)

        if new_score < current_score or random.random() < 2.718**((current_score - new_score) / T):
            current_score = new_score
            if current_score < min_score:
                min_score = current_score
        else:
            board[r1][c1], board[r2][c2] = board[r2][c2], board[r1][c1]

        T *= alpha

    return min_score

